using System;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Interop;
using MapleMeter;
namespace MapleWarm {
 public sealed class Settings:Surface {
  readonly Meter main;readonly Engine engine;Button a,c;
  public Settings(Meter main,Engine engine):base("MapleMeter 暖光版 · 设置",480,562){this.main=main;this.engine=engine;Build();App.FontChanged+=Build;Closed+=delegate{App.FontChanged-=Build;};}
  void Build(){Reset();Header("设置");SkinChoices();ScaleChoices();App.At(canvas,App.Text("界面字体",14,null,true),24,182,432,28);a=App.Button((App.Wen?"":"✓ ")+"A · 思源黑体 + Inter",null,()=>Choose(false));c=App.Button((App.Wen?"✓ ":"")+"C · 霞鹜文楷 + Inter",null,()=>Choose(true));App.At(canvas,a,24,218,432,42);App.At(canvas,c,24,270,432,42);
   App.At(canvas,App.Text("更多设置",12,App.Muted),24,387,432,24);string[] labels={"选择窗口","识别区域","重新定位","导入经验表","使用说明","打开记录目录"};Action[] actions={Pick,Calibrate,()=>engine.ResetLocation(),Import,Help,()=>{Directory.CreateDirectory(Storage.Folder);System.Diagnostics.Process.Start("explorer.exe",Storage.Folder);}};for(int i=0;i<labels.Length;i++){int index=i;App.At(canvas,App.Button(labels[i],null,()=>Safe(actions[index])),24+i%3*148,421+i/3*48,136,38);}var diagnostic=App.Text("v"+typeof(App).Assembly.GetName().Version.ToString(3)+" · "+engine.Diagnostic,11,App.Muted);diagnostic.ToolTip=engine.Diagnostic;App.At(canvas,diagnostic,24,522,432,24);}
  void SkinChoices(){App.At(canvas,App.Text("界面皮肤",14,null,true),24,50,432,28);string[] ids={"mint","warm","sky"},names={"静夜薄荷","枫糖暖光","晴空轻白"},fills={"#192431","#FFF5E6","#F4F9FF"},inks={"#DCE9F9","#542712","#18314F"},accents={"#86EAB1","#ED8253","#2289FF"};for(int i=0;i<3;i++){string id=ids[i];var button=App.Button("",null,()=>Safe(()=>Theme.Set(id)));var panel=new Grid{Width=124,Height=66};var stripe=new System.Windows.Shapes.Rectangle{Height=4,VerticalAlignment=VerticalAlignment.Top,Fill=(System.Windows.Media.Brush)new System.Windows.Media.BrushConverter().ConvertFromString(accents[i]),Margin=new Thickness(14,10,14,0)};panel.Children.Add(stripe);var label=App.Text(names[i],13,(System.Windows.Media.Brush)new System.Windows.Media.BrushConverter().ConvertFromString(inks[i]),Theme.Id==id);label.TextAlignment=TextAlignment.Center;label.Margin=new Thickness(0,12,0,0);panel.Children.Add(label);button.Content=panel;button.Background=(System.Windows.Media.Brush)new System.Windows.Media.BrushConverter().ConvertFromString(fills[i]);button.BorderBrush=Theme.Id==id?(System.Windows.Media.Brush)new System.Windows.Media.BrushConverter().ConvertFromString(accents[i]):App.Line;button.ToolTip=names[i]+(Theme.Id==id?" · 当前使用":"");App.At(canvas,button,24+i*148,86,136,72);}}
  void ScaleChoices(){App.At(canvas,App.Text("界面缩放",12,App.Muted),24,326,104,36);double[] scales={.8,.9,1,1.25,1.5};for(int i=0;i<scales.Length;i++){double scale=scales[i];App.At(canvas,App.Button((App.UiScale==scale?"✓ ":"")+(scale*100).ToString("0")+"%",null,()=>Safe(()=>App.SetScale(scale))),128+i*66,326,62,36);}}
  void Choose(bool value){Safe(()=>App.SetFont(value));}
  void Safe(Action action){try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"MapleMeter 暖光版");}}
  void Pick(){var dialog=new Surface("MapleMeter 暖光版 · 选择窗口",520,340){Owner=this};var panel=new Grid{Margin=new Thickness(24)};panel.RowDefinitions.Add(new RowDefinition{Height=new GridLength(30)});panel.RowDefinitions.Add(new RowDefinition());panel.RowDefinitions.Add(new RowDefinition{Height=new GridLength(44)});panel.Children.Add(App.Text("选择画面来源",18,null,true));var list=new ListBox{ItemsSource=Native.Windows(true),FontFamily=App.Chinese,FontSize=14,FontWeight=App.BodyWeight,Background=App.Brush("#FFF9EF"),Foreground=App.Ink,BorderBrush=App.Line,Margin=new Thickness(0,12,0,12)};Grid.SetRow(list,1);panel.Children.Add(list);var connect=App.Button("连接选中窗口",null,()=>{if(list.SelectedItem!=null){Safe(()=>{engine.SelectWindow((GameWindow)list.SelectedItem);dialog.Close();});}});Grid.SetRow(connect,2);panel.Children.Add(connect);dialog.Content=App.Card(panel,App.Brush("#FFF9EF"),18,true);dialog.ShowDialog();}
  void Calibrate(){if(engine.LatestStrip==null){engine.Notify("请先切回游戏");return;}using(var form=new CalibrationForm(engine.LatestStrip,engine.ExpRect,engine.LevelRect)){if(form.ShowDialog(new NativeOwner(new WindowInteropHelper(this).Handle))==System.Windows.Forms.DialogResult.OK)engine.ApplyCalibration(form.Exp,form.Level);}}
  void Import(){var dialog=new Microsoft.Win32.OpenFileDialog{Title="导入等级经验表",Filter="CSV 文件|*.csv"};if(dialog.ShowDialog(this)==true){engine.ImportTable(dialog.FileName);engine.Notify("经验表已导入");}}
  void Help(){MessageBox.Show(this,"游戏状态栏可见时自动识别。15 秒无操作自动暂停，经验变化后恢复。\n连续暂停 15 分钟后自动结束并保存。\n请展开左上方小地图。有效时长超过 10 分钟的记录会保留。\n\nCtrl+Alt+空格：手动暂停 / 继续\nCtrl+Alt+L：返回主窗口\n\n只读取屏幕，不读取游戏内存、不发送游戏操作。\n暖光版使用独立设置与历史目录。","使用说明");}
  sealed class NativeOwner:System.Windows.Forms.IWin32Window{public IntPtr Handle{get;private set;}public NativeOwner(IntPtr handle){Handle=handle;}}
 }
}
